# Build the output grid
input_grid = [
    [4, 4, 4, 4, 4, 4, 0, 0, 0, 0, 0, 0, 0, 0, 4, 4, 4, 2, 4, 4],
    [4, 4, 4, 4, 4, 4, 0, 0, 0, 0, 0, 0, 0, 0, 4, 4, 2, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 0, 0, 0, 0, 0, 0, 0, 0, 4, 2, 4, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 0, 0, 0, 0, 0, 0, 0, 0, 2, 4, 4, 4, 4, 4],
]

output = []
for r in range(24):
    row = input_grid[r][:] if r >= 4 else []
    for c in range(20):
        if r == 0 and c == 17:
            row.append(3)
        elif r == 1 and c == 16:
            row.append(3)
        elif r == 2 and c == 15:
            row.append(3)
        elif r == 3 and c == 14:
            row.append(3)
        elif r < 4:
            val = input_grid[r][c]
            row.append(val if val != 2 else 3 if (r,c) in [(0,17),(1,16),(2,15),(3,14)] else val)
        else:
            row.append(input_grid[r][c])

print([list(row) for row in output])

